package main

import (
	"testing"
)

func TestSignerCache(t *testing.T) {
	sc := newSignerCache(300)

	// Empty cache
	if _, ok := sc.get(); ok {
		t.Error("expected empty cache")
	}

	// Set and get
	signers := []signerResponse{
		{ID: "s1", Name: "signer-1"},
		{ID: "s2", Name: "signer-2"},
	}
	sc.set(signers)

	result, ok := sc.get()
	if !ok {
		t.Fatal("expected cached signers")
	}
	if len(result) != 2 {
		t.Errorf("expected 2 signers, got %d", len(result))
	}
	if result[0].Name != "signer-1" {
		t.Errorf("expected signer-1, got %s", result[0].Name)
	}

	// Invalidate
	sc.invalidate()
	if _, ok := sc.get(); ok {
		t.Error("expected empty cache after invalidate")
	}
}

func TestCertDataCache(t *testing.T) {
	cdc := newCertDataCache(3600)

	// Empty cache
	if _, ok := cdc.getPubKey("s1"); ok {
		t.Error("expected empty pub key cache")
	}
	if _, ok := cdc.getCert("s1"); ok {
		t.Error("expected empty cert cache")
	}

	// Set and get pub key
	pk := pubKeyEntry{PublicKeyDER: []byte{1, 2, 3}, Algorithm: "rsa"}
	cdc.setPubKey("s1", pk)
	result, ok := cdc.getPubKey("s1")
	if !ok {
		t.Fatal("expected cached pub key")
	}
	if result.Algorithm != "rsa" {
		t.Errorf("expected rsa, got %s", result.Algorithm)
	}

	// Set and get cert
	cert := []byte{4, 5, 6}
	cdc.setCert("s1", cert)
	certResult, ok := cdc.getCert("s1")
	if !ok {
		t.Fatal("expected cached cert")
	}
	if len(certResult) != 3 {
		t.Errorf("expected 3 bytes, got %d", len(certResult))
	}
}

package main

import (
	"encoding/asn1"
	"testing"

	"github.com/miekg/pkcs11"
)

func TestMechanismToAlgorithm(t *testing.T) {
	tests := []struct {
		name      string
		mechanism uint
		expected  string
		wantErr   bool
	}{
		{"SHA256_RSA_PKCS", pkcs11.CKM_SHA256_RSA_PKCS, AlgRSAPKCS1SHA256, false},
		{"SHA384_RSA_PKCS", pkcs11.CKM_SHA384_RSA_PKCS, AlgRSAPKCS1SHA384, false},
		{"SHA512_RSA_PKCS", pkcs11.CKM_SHA512_RSA_PKCS, AlgRSAPKCS1SHA512, false},
		{"SHA256_RSA_PKCS_PSS", pkcs11.CKM_SHA256_RSA_PKCS_PSS, AlgRSAPSSSHA256, false},
		{"ECDSA_SHA256", pkcs11.CKM_ECDSA_SHA256, AlgECDSASHA256, false},
		{"ECDSA_SHA384", pkcs11.CKM_ECDSA_SHA384, AlgECDSASHA384, false},
		{"ECDSA_SHA512", pkcs11.CKM_ECDSA_SHA512, AlgECDSASHA512, false},
		{"ECDSA (raw)", pkcs11.CKM_ECDSA, AlgECDSASHA256, false},
		{"CKM_RSA_PKCS requires DigestInfo", pkcs11.CKM_RSA_PKCS, "", true},
		{"unsupported mechanism", 0xFFFFFFFF, "", true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			alg, err := mechanismToAlgorithm(tt.mechanism)
			if tt.wantErr {
				if err == nil {
					t.Errorf("expected error, got nil")
				}
				return
			}
			if err != nil {
				t.Errorf("unexpected error: %v", err)
				return
			}
			if alg != tt.expected {
				t.Errorf("expected %s, got %s", tt.expected, alg)
			}
		})
	}
}

// buildDigestInfo creates a DER-encoded DigestInfo structure.
func buildDigestInfo(oid asn1.ObjectIdentifier, digest []byte) []byte {
	algID, _ := asn1.Marshal(algorithmIdentifier{
		Algorithm:  oid,
		Parameters: asn1.RawValue{Tag: 5}, // NULL
	})

	di := digestInfo{
		DigestAlgorithm: asn1.RawValue{FullBytes: algID},
		Digest:          digest,
	}

	data, _ := asn1.Marshal(di)
	return data
}

func TestParseDigestInfo(t *testing.T) {
	sha256Digest := make([]byte, 32) // 256 bits
	sha384Digest := make([]byte, 48)
	sha512Digest := make([]byte, 64)

	tests := []struct {
		name     string
		data     []byte
		expected string
		wantErr  bool
	}{
		{
			"SHA-256 DigestInfo",
			buildDigestInfo(oidSHA256, sha256Digest),
			AlgRSAPKCS1SHA256,
			false,
		},
		{
			"SHA-384 DigestInfo",
			buildDigestInfo(oidSHA384, sha384Digest),
			AlgRSAPKCS1SHA384,
			false,
		},
		{
			"SHA-512 DigestInfo",
			buildDigestInfo(oidSHA512, sha512Digest),
			AlgRSAPKCS1SHA512,
			false,
		},
		{
			"invalid data",
			[]byte{0x01, 0x02, 0x03},
			"",
			true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			alg, _, err := parseDigestInfo(tt.data)
			if tt.wantErr {
				if err == nil {
					t.Errorf("expected error, got nil")
				}
				return
			}
			if err != nil {
				t.Errorf("unexpected error: %v", err)
				return
			}
			if alg != tt.expected {
				t.Errorf("expected %s, got %s", tt.expected, alg)
			}
		})
	}
}

package main

import (
	"testing"
)

func TestObjectHandles(t *testing.T) {
	privHandle := makePrivateKeyHandle(5)
	pubHandle := makePublicKeyHandle(5)
	certHandle := makeCertificateHandle(5)

	objType, slotIdx := parseObjectHandle(privHandle)
	if objType != objPrivateKey {
		t.Errorf("expected objPrivateKey, got 0x%08x", objType)
	}
	if slotIdx != 5 {
		t.Errorf("expected slot index 5, got %d", slotIdx)
	}

	objType, slotIdx = parseObjectHandle(pubHandle)
	if objType != objPublicKey {
		t.Errorf("expected objPublicKey, got 0x%08x", objType)
	}
	if slotIdx != 5 {
		t.Errorf("expected slot index 5, got %d", slotIdx)
	}

	objType, slotIdx = parseObjectHandle(certHandle)
	if objType != objCertificate {
		t.Errorf("expected objCertificate, got 0x%08x", objType)
	}
	if slotIdx != 5 {
		t.Errorf("expected slot index 5, got %d", slotIdx)
	}
}

func TestSessionManager(t *testing.T) {
	sm := newSessionManager()

	// Open sessions
	h1 := sm.open(0)
	h2 := sm.open(0)
	h3 := sm.open(1)

	// Get sessions
	s1, ok := sm.get(h1)
	if !ok || s1.slotID != 0 {
		t.Error("failed to get session 1")
	}

	s3, ok := sm.get(h3)
	if !ok || s3.slotID != 1 {
		t.Error("failed to get session 3")
	}

	// Close session
	if !sm.close(h2) {
		t.Error("failed to close session 2")
	}
	if _, ok := sm.get(h2); ok {
		t.Error("session 2 should be closed")
	}

	// Close all for slot 0
	sm.closeAllForSlot(0)
	if _, ok := sm.get(h1); ok {
		t.Error("session 1 should be closed after closeAllForSlot(0)")
	}
	if _, ok := sm.get(h3); !ok {
		t.Error("session 3 should still be open")
	}

	// Set logged in (per-session)
	sm.setLoggedIn(h3, true)
	s3, ok = sm.get(h3)
	if !ok || !s3.loggedIn {
		t.Error("session 3 should be logged in")
	}

	// Test setAllLoggedInForSlot
	h4 := sm.open(1)
	sm.setAllLoggedInForSlot(1, true)
	s4, ok := sm.get(h4)
	if !ok || !s4.loggedIn {
		t.Error("session 4 should be logged in after setAllLoggedInForSlot")
	}

	// Test appendSignBuffer limits
	s4.signActive = true
	if err := s4.appendSignBuffer(make([]byte, 100)); err != nil {
		t.Errorf("unexpected error on small buffer: %v", err)
	}
	bigBuf := make([]byte, maxSignBuffer+1)
	if err := s4.appendSignBuffer(bigBuf); err == nil {
		t.Error("expected error on buffer exceeding maxSignBuffer")
	}
}

package main

import (
	"testing"

	"github.com/miekg/pkcs11"
)

func TestMapHTTPError(t *testing.T) {
	tests := []struct {
		name       string
		statusCode int
		expected   uint
	}{
		{"401 -> USER_NOT_LOGGED_IN", 401, pkcs11.CKR_USER_NOT_LOGGED_IN},
		{"403 -> GENERAL_ERROR", 403, pkcs11.CKR_GENERAL_ERROR},
		{"404 -> KEY_HANDLE_INVALID", 404, pkcs11.CKR_KEY_HANDLE_INVALID},
		{"400 -> DATA_INVALID", 400, pkcs11.CKR_DATA_INVALID},
		{"500 -> DEVICE_ERROR", 500, pkcs11.CKR_DEVICE_ERROR},
		{"502 -> DEVICE_ERROR", 502, pkcs11.CKR_DEVICE_ERROR},
		{"418 -> GENERAL_ERROR", 418, pkcs11.CKR_GENERAL_ERROR},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := mapHTTPError(tt.statusCode)
			if result != tt.expected {
				t.Errorf("expected 0x%08x, got 0x%08x", tt.expected, result)
			}
		})
	}
}

func TestIsUnsupportedMechanismMessage(t *testing.T) {
	tests := []struct {
		name string
		msg  string
		want bool
	}{
		{"gateway structured code", "PKCS#11 request failed (mechanism_invalid): The HSM does not support the requested signing algorithm", true},
		{"gateway HSM phrase", "Mechanism not supported by this HSM", true},
		{"api pre-check phrase", "Signing algorithm RSASSA_PKCS1_V1_5_SHA_256 is not supported on HSM-backed certificates", true},
		{"unsupported wording", "unsupported mechanism", true},
		{"key/algorithm mismatch is NOT a mechanism issue", "RSA key cannot be used with signing algorithm ECDSA_SHA_256", false},
		{"generic bad request", "Data exceeds maximum size of 128 bytes", false},
		{"key not found", "Private key with label \"x\" not found", false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := isUnsupportedMechanismMessage(tt.msg); got != tt.want {
				t.Errorf("isUnsupportedMechanismMessage(%q) = %v, want %v", tt.msg, got, tt.want)
			}
		})
	}
}

func TestMapAPIError(t *testing.T) {
	tests := []struct {
		name     string
		apiErr   *APIError
		expected uint
	}{
		{"mechanism invalid -> MECHANISM_INVALID", &APIError{StatusCode: 400, Message: "PKCS#11 request failed (mechanism_invalid): ..."}, pkcs11.CKR_MECHANISM_INVALID},
		{"plain 400 -> DATA_INVALID", &APIError{StatusCode: 400, Message: "Data exceeds maximum size"}, pkcs11.CKR_DATA_INVALID},
		{"401 -> USER_NOT_LOGGED_IN", &APIError{StatusCode: 401, Message: "unauthorized"}, pkcs11.CKR_USER_NOT_LOGGED_IN},
		{"500 -> DEVICE_ERROR", &APIError{StatusCode: 500, Message: "internal"}, pkcs11.CKR_DEVICE_ERROR},
		{"401 with mechanism message stays USER_NOT_LOGGED_IN", &APIError{StatusCode: 401, Message: "Mechanism not supported"}, pkcs11.CKR_USER_NOT_LOGGED_IN},
		{"403 with mechanism message stays GENERAL_ERROR", &APIError{StatusCode: 403, Message: "algorithm not supported for this context"}, pkcs11.CKR_GENERAL_ERROR},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := mapAPIError(tt.apiErr); got != tt.expected {
				t.Errorf("expected 0x%08x, got 0x%08x", tt.expected, got)
			}
		})
	}
}

func TestIsApprovalRequired(t *testing.T) {
	cases := []struct {
		name string
		err  *APIError
		want bool
	}{
		// Bodies captured from a live instance: the sign route sets error to the thrown error's
		// name, which is why the code is authoritative here.
		{"403 approval required", &APIError{StatusCode: 403, Code: "ApprovalRequired"}, true},
		{"403 generic forbidden name", &APIError{StatusCode: 403, Code: "ForbiddenError"}, false},
		{"403 permission denied", &APIError{StatusCode: 403, Code: "PermissionDenied"}, false},
		{"403 token error", &APIError{StatusCode: 403, Code: "TokenError"}, false},
		{"403 with no code (proxy or WAF, not Infisical)", &APIError{StatusCode: 403, Code: ""}, false},
		{"401", &APIError{StatusCode: 401, Code: "ApprovalRequired"}, false},
		{"404", &APIError{StatusCode: 404, Code: ""}, false},
		{"500", &APIError{StatusCode: 500, Code: ""}, false},
	}
	for _, c := range cases {
		if got := c.err.IsApprovalRequired(); got != c.want {
			t.Errorf("%s: IsApprovalRequired() = %v, want %v", c.name, got, c.want)
		}
	}
}

func TestRedactionCoversPropertyStyleCredentials(t *testing.T) {
	cases := []struct {
		name string
		args []string
		want string
	}{
		{"gradle property", []string{"gradle", "-Psigning.password=s3cret"}, "gradle -Psigning.password=***"},
		{"gradle camel case", []string{"gradle", "-PsigningPassword=s3cret"}, "gradle -PsigningPassword=***"},
		{"java system property", []string{"java", "-Dsigning.keyPassword=s3cret"}, "java -Dsigning.keyPassword=***"},
		{"bare assignment", []string{"make", "PASSWORD=s3cret"}, "make PASSWORD=***"},
		{"msbuild sub-key", []string{"msbuild", "/p:Password=s3cret"}, "msbuild /p:Password=***"},
		{"separate value", []string{"jarsigner", "-storepass", "hunter2"}, "jarsigner -storepass ***"},
		// A secret flag given no value must not consume the following flag's value.
		{"missing value", []string{"jarsigner", "-storepass", "-keypass", "hunter3"}, "jarsigner -storepass -keypass ***"},
		{"passwd suffix", []string{"tool", "--db-passwd=s3cret"}, "tool --db-passwd=***"},
		{"colon value", []string{"tool", "-pass:s3cret"}, "tool -pass:***"},
		// A sub-key without an inline value must not swallow the next argument.
		{"sub-key without value", []string{"signtool", "/p:pass", "app.exe"}, "signtool /p:*** app.exe"},
	}
	for _, c := range cases {
		if got := joinCommandArgs(redactCommandArgs(c.args)); got != c.want {
			t.Errorf("%s:\n  got  %s\n  want %s", c.name, got, c.want)
		}
	}
}

package main

import (
	"encoding/json"
	"strings"
	"testing"
	"unicode/utf8"
)

func capturedCommand(args ...string) string {
	return truncateCommand(joinCommandArgs(redactCommandArgs(args)))
}

func TestRedactCommandSecrets(t *testing.T) {
	cases := []struct {
		name string
		in   []string
		want string
	}{
		{
			name: "jarsigner store and key passwords",
			in:   []string{"jarsigner", "-storepass", "hunter2", "-keypass", "hunter3", "-keystore", "ks.jks", "app.jar", "alias"},
			want: "jarsigner -storepass *** -keypass *** -keystore ks.jks app.jar alias",
		},
		{
			name: "signtool slash p",
			in:   []string{"signtool", "sign", "/fd", "SHA256", "/p", "s3cret", "/f", "cert.pfx", "app.exe"},
			want: "signtool sign /fd SHA256 /p *** /f cert.pfx app.exe",
		},
		{
			name: "osslsigncode pass",
			in:   []string{"osslsigncode", "sign", "-pass", "topsecret", "-in", "app.exe", "-out", "signed.exe"},
			want: "osslsigncode sign -pass *** -in app.exe -out signed.exe",
		},
		{
			name: "equals form",
			in:   []string{"tool", "--password=topsecret", "--other=keep"},
			want: "tool --password=*** --other=keep",
		},
		{
			name: "pkcs11 pin",
			in:   []string{"pkcs11-tool", "--pin", "1234", "--sign"},
			want: "pkcs11-tool --pin *** --sign",
		},
		{
			name: "case insensitive flag",
			in:   []string{"tool", "-StorePass", "hunter2"},
			want: "tool -StorePass ***",
		},
		{
			name: "nothing to redact is unchanged",
			in:   []string{"signtool", "sign", "/fd", "SHA256", "/f", "cert.cer", "app.exe"},
			want: "signtool sign /fd SHA256 /f cert.cer app.exe",
		},
		{
			name: "flag with no value is left alone",
			in:   []string{"tool", "--password"},
			want: "tool --password",
		},
		{
			name: "a value that looks like a flag is still redacted",
			in:   []string{"tool", "-pass", "--notaflag"},
			want: "tool -pass ***",
		},
		{
			name: "redaction is idempotent",
			in:   []string{"jarsigner", "-storepass", "***", "app.jar"},
			want: "jarsigner -storepass *** app.jar",
		},

		// The cases below all leaked when redaction ran on a space-joined string. Each is a
		// realistic way a credential reaches a signing tool, so they are kept as regressions.
		{
			name: "a password containing a space is redacted whole",
			in:   []string{"jarsigner", "-storepass", "my pass", "app.jar"},
			want: "jarsigner -storepass *** app.jar",
		},
		{
			name: "a quoted password is redacted whole",
			in:   []string{"signtool", "sign", "/p", "my pass", "app.exe"},
			want: "signtool sign /p *** app.exe",
		},
		{
			name: "an argument separated by extra whitespace is still the value",
			in:   []string{"tool", "--password", "hunter2", "app.exe"},
			want: "tool --password *** app.exe",
		},
		{
			name: "msbuild property form",
			in:   []string{"msbuild", "/p:Password=s3cret", "app.sln"},
			want: "msbuild /p:Password=*** app.sln",
		},
		{
			name: "msbuild property named with a password suffix",
			in:   []string{"msbuild", "/p:CertPassword=s3cret", "/p:Configuration=Release"},
			want: "msbuild /p:CertPassword=*** /p:Configuration=Release",
		},
		{
			name: "an empty credential still reports as redacted",
			in:   []string{"signtool", "sign", "/p", "", "app.exe"},
			want: "signtool sign /p *** app.exe",
		},
		{
			name: "a non-secret value containing a space keeps its quoting",
			in:   []string{"signtool", "sign", "/csp", "Infisical Key Storage Provider", "app.exe"},
			want: `signtool sign /csp "Infisical Key Storage Provider" app.exe`,
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := capturedCommand(c.in...); got != c.want {
				t.Fatalf("captured command\n got: %q\nwant: %q", got, c.want)
			}
		})
	}
}

// Asserts on absence rather than on an expected string, so this still fails if the redaction rules change
// shape.
func TestNoCredentialSurvivesCapture(t *testing.T) {
	const secret = "s3cret"
	argvs := [][]string{
		{"jarsigner", "-storepass", secret},
		{"jarsigner", "-storepass", secret + " with spaces"},
		{"signtool", "sign", "/p", secret},
		{"tool", "--password=" + secret},
		{"msbuild", "/p:Password=" + secret},
		{"msbuild", "/property:SignPassphrase=" + secret},
		{"pkcs11-tool", "--pin", secret},
		{"tool", "-PassIn", secret},
	}

	for _, argv := range argvs {
		if got := capturedCommand(argv...); strings.Contains(got, secret) {
			t.Fatalf("a credential survived capture of %q: %q", argv, got)
		}
	}
}

func TestRedactionRunsBeforeTruncation(t *testing.T) {
	padded := []string{"jarsigner", "-storepass", "hunter2", strings.Repeat("a", maxCommandLen)}
	got := capturedCommand(padded...)

	if strings.Contains(got, "hunter2") {
		t.Fatal("the password survived into the captured command line")
	}
	if !strings.Contains(got, "-storepass "+redactedValue) {
		t.Fatalf("expected a redacted password, got %q", got[:60])
	}
}

// An argument the OS reports as one element must come back as one token on the server, so a
// value containing whitespace has to be re-quoted rather than joined bare.
func TestJoinCommandArgsQuotesWhitespace(t *testing.T) {
	cases := []struct {
		in   []string
		want string
	}{
		{in: []string{"a", "b"}, want: "a b"},
		{in: []string{"a", "b c"}, want: `a "b c"`},
		{in: []string{"a", "b\tc"}, want: "a \"b\tc\""},
		{in: []string{"a", "", "b"}, want: `a "" b`},
	}

	for _, c := range cases {
		if got := joinCommandArgs(c.in); got != c.want {
			t.Fatalf("joinCommandArgs(%q)\n got: %q\nwant: %q", c.in, got, c.want)
		}
	}
}

func TestTruncateCommand(t *testing.T) {
	short := "signtool sign app.exe"
	if got := truncateCommand(short); got != short {
		t.Fatalf("a short command must pass through unchanged, got %q", got)
	}

	long := strings.Repeat("x", maxCommandLen+50)
	if got := truncateCommand(long); len(got) != maxCommandLen {
		t.Fatalf("expected %d bytes, got %d", maxCommandLen, len(got))
	}

	// A multi-byte rune straddling the cut must not be split in half.
	straddling := strings.Repeat("x", maxCommandLen-1) + "é" + "tail"
	got := truncateCommand(straddling)
	if !utf8.ValidString(got) {
		t.Fatalf("truncation produced invalid UTF-8: %q", got[len(got)-4:])
	}
	if len(got) != maxCommandLen-1 {
		t.Fatalf("expected the cut to fall back to %d bytes, got %d", maxCommandLen-1, len(got))
	}
}

// wireKeys marshals a payload and returns the JSON object it actually sends. The struct field
// names are the compiler's job; these are the wire names, which only the tags control.
func wireKeys(t *testing.T, payload any) map[string]string {
	t.Helper()

	raw, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshalling the payload failed: %v", err)
	}
	var out map[string]string
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatalf("the payload did not marshal to a flat object: %v (%s)", err, raw)
	}
	return out
}

func TestClientMetadataKeysMatchScopeKeys(t *testing.T) {
	ctx := signingContext{
		Command:         "signtool sign app.exe",
		Application:     "signtool",
		ApplicationHash: "abc",
		Hostname:        "build-01",
		OSUsername:      "svc",
	}

	md := wireKeys(t, ctx.clientMetadata())
	scope := wireKeys(t, ctx.requestScope("digest", nil, ""))

	// 'tool' is the only key that differs by name, mapped in buildObservedSigningContext
	// (backend/src/services/approval-policy/code-signing/code-signing-policy-fns.ts). Every other key
	// matches by name, so a rename on one side has to be mirrored on the other.
	if md["tool"] != scope["signingApplication"] {
		t.Fatalf("clientMetadata tool %q must carry the scope's signingApplication %q", md["tool"], scope["signingApplication"])
	}
	for _, key := range []string{"command", "signingApplicationHash", "hostname", "osUsername"} {
		if md[key] != scope[key] {
			t.Fatalf("key %q differs: metadata %q, scope %q", key, md[key], scope[key])
		}
	}
}

// The scope parameter names are a server contract, so they are pinned here: a renamed tag would
// otherwise leave the parameter unconstrained and silently widen every approval.
func TestScopeWireNames(t *testing.T) {
	full := signingContext{
		Command:         "signtool sign app.exe",
		Application:     "signtool",
		ApplicationHash: "abc",
		Hostname:        "build-01",
		OSUsername:      "svc",
	}.requestScope("digest", nil, "")

	got := wireKeys(t, full)
	want := []string{"command", "signingApplication", "signingApplicationHash", "hostname", "osUsername", "dataHash"}

	for _, key := range want {
		if _, ok := got[key]; !ok {
			t.Fatalf("scope parameter %q is missing from the wire payload %v", key, got)
		}
	}
	if len(got) != len(want) {
		t.Fatalf("expected exactly %d scope parameters, got %v", len(want), got)
	}
}

func TestRequestScopeOmitsEmptyFieldsAndNeverDeclaresIP(t *testing.T) {
	scope := wireKeys(t, signingContext{Hostname: "build-01"}.requestScope("digest", nil, ""))

	if _, ok := scope["command"]; ok {
		t.Fatal("an empty field must be omitted rather than sent blank")
	}
	if _, ok := scope["ipAddress"]; ok {
		t.Fatal("the module must never declare an IP address")
	}
	if scope["hostname"] != "build-01" || scope["dataHash"] != "digest" {
		t.Fatalf("expected the hostname and digest to be declared, got %v", scope)
	}
}

// The digest is what makes the scope meaningful, so an all-empty context must not produce a
// request that would grant broadly scoped signing.
func TestRequestScopeAlwaysCarriesTheDigest(t *testing.T) {
	scope := wireKeys(t, signingContext{}.requestScope("digest", nil, ""))
	if scope["dataHash"] != "digest" {
		t.Fatalf("expected the digest to be declared even with no other context, got %v", scope)
	}
}

func TestRequestScopeOmitsExcludedFields(t *testing.T) {
	ctx := signingContext{
		Command:         "signtool sign app.exe",
		Application:     "signtool",
		ApplicationHash: "abc",
		Hostname:        "build-01",
		OSUsername:      "svc",
	}

	scope := ctx.requestScope("digest", []string{scopeFieldDataHash}, "")
	if scope.DataHash != "" {
		t.Fatalf("expected data_hash to be excluded, got %q", scope.DataHash)
	}
	if scope.Command != ctx.Command || scope.Hostname != ctx.Hostname || scope.OSUsername != ctx.OSUsername {
		t.Fatalf("excluding one parameter must not drop the others: %+v", scope)
	}
	if _, present := wireBody(t, scope)["dataHash"]; present {
		t.Fatal("an excluded parameter must not appear in the request body")
	}

	if kept := ctx.requestScope("digest", nil, ""); kept.DataHash != "digest" {
		t.Fatalf("no exclusions must keep every parameter, got %+v", kept)
	}
}

func TestRequestScopeAddressIsAbsentPinnedOrSkipped(t *testing.T) {
	ctx := signingContext{Command: "signtool sign app.exe", Hostname: "build-01"}

	if _, present := wireBody(t, ctx.requestScope("digest", nil, ""))["ipAddress"]; present {
		t.Fatal("an address this module did not pin must be left for Infisical to fill in")
	}

	pinned := wireBody(t, ctx.requestScope("digest", nil, "203.0.113.10"))["ipAddress"]
	if pinned != "203.0.113.10" {
		t.Fatalf("a pinned address must reach the server verbatim, got %v", pinned)
	}

	skipped, present := wireBody(t, ctx.requestScope("digest", []string{scopeFieldIPAddress}, ""))["ipAddress"]
	if !present || skipped != nil {
		t.Fatalf("excluding ip_address must send an explicit null, got %v (present=%v)", skipped, present)
	}

	both, present := wireBody(t, ctx.requestScope("digest", []string{scopeFieldIPAddress}, "203.0.113.10"))["ipAddress"]
	if !present || both != nil {
		t.Fatalf("excluding must override a pinned address, got %v (present=%v)", both, present)
	}
}

func TestValidateScopeExclusions(t *testing.T) {
	if err := ValidateScopeExclusions([]string{scopeFieldDataHash, scopeFieldIPAddress}); err != nil {
		t.Fatalf("known field names must validate: %v", err)
	}
	if err := ValidateScopeExclusions(nil); err != nil {
		t.Fatalf("no exclusions must validate: %v", err)
	}
	if err := ValidateScopeExclusions([]string{"dataHash"}); err == nil {
		t.Fatal("expected the camelCase spelling to be rejected")
	}
}

func wireBody(t *testing.T, payload any) map[string]any {
	t.Helper()

	raw, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshalling the payload failed: %v", err)
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatalf("the payload did not marshal to an object: %v (%s)", err, raw)
	}
	return out
}

