func TestLoadConfigValidation(t *testing.T) {
	dir := t.TempDir()
	configPath := filepath.Join(dir, "pkcs11.conf")

	tests := []struct {
		name    string
		config  string
		wantErr bool
	}{
		{
			name:    "missing server_url",
			config:  `{}`,
			wantErr: true,
		},
		{
			name:    "unsupported auth method",
			config:  `{"server_url": "https://app.infisical.com", "auth": {"method": "oauth"}}`,
			wantErr: true,
		},
		{
			name:    "rejects non-http(s) scheme",
			config:  `{"server_url": "file:///etc/passwd"}`,
			wantErr: true,
		},
		{
			name:    "rejects bare path without scheme",
			config:  `{"server_url": "app.infisical.com"}`,
			wantErr: true,
		},
		{
			name:    "accepts http for local dev",
			config:  `{"server_url": "http://localhost:8080"}`,
			wantErr: false,
		},
		{
			name:    "accepts https",
			config:  `{"server_url": "https://app.infisical.com"}`,
			wantErr: false,
		},
		{
			name:    "rejects an unknown scope exclusion",
			config:  `{"server_url": "https://app.infisical.com", "approval": {"exclude_scope_fields": ["dataHash"]}}`,
			wantErr: true,
		},
		{
			name:    "rejects an ip_address that is not an address",
			config:  `{"server_url": "https://app.infisical.com", "approval": {"ip_address": "build-agent-02"}}`,
			wantErr: true,
		},
		{
			name:    "accepts an exclusion and a pinned address",
			config:  `{"server_url": "https://app.infisical.com", "approval": {"exclude_scope_fields": ["data_hash"], "ip_address": "203.0.113.10"}}`,
			wantErr: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if err := os.WriteFile(configPath, []byte(tt.config), 0600); err != nil {
				t.Fatal(err)
			}
			t.Setenv(envConfigPath, configPath)

			_, err := loadConfig()
			if tt.wantErr && err == nil {
				t.Errorf("expected error, got nil")
			}
			if !tt.wantErr && err != nil {
				t.Errorf("unexpected error: %v", err)
			}
		})
	}
}

func TestDefaultConfigPathFor(t *testing.T) {
	cases := []struct {
		name        string
		goos        string
		programData string
		want        string
	}{
		{"linux", "linux", "", unixDefaultConfigPath},
		{"darwin", "darwin", `C:\ProgramData`, unixDefaultConfigPath},
		{"windows", "windows", `D:\Data`, `D:\Data\Infisical\pkcs11.conf`},
		{"windows without ProgramData set", "windows", "", `C:\ProgramData\Infisical\pkcs11.conf`},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if got := defaultConfigPathFor(c.goos, c.programData); got != c.want {
				t.Fatalf("defaultConfigPathFor(%q, %q) = %q, want %q", c.goos, c.programData, got, c.want)
			}
		})
	}

	if got := defaultConfigPath(); got != defaultConfigPathFor(runtime.GOOS, os.Getenv("ProgramData")) {
		t.Fatalf("defaultConfigPath() disagrees with defaultConfigPathFor: %q", got)
	}
}

package main

import (
	"sync"
	"time"
)

type cacheEntry[T any] struct {
	value     T
	expiresAt time.Time
}

func (e *cacheEntry[T]) isExpired() bool {
	return time.Now().After(e.expiresAt)
}

type signerCache struct {
	mu    sync.RWMutex
	ttl   time.Duration
	entry *cacheEntry[[]signerResponse]
}

func newSignerCache(ttlSeconds int) *signerCache {
	if ttlSeconds == 0 {
		ttlSeconds = 300
	}
	return &signerCache{ttl: time.Duration(ttlSeconds) * time.Second}
}

func (c *signerCache) get() ([]signerResponse, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	if c.entry == nil || c.entry.isExpired() {
		return nil, false
	}
	return c.entry.value, true
}

func (c *signerCache) set(signers []signerResponse) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.entry = &cacheEntry[[]signerResponse]{
		value:     signers,
		expiresAt: time.Now().Add(c.ttl),
	}
}

func (c *signerCache) invalidate() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.entry = nil
}

type pubKeyEntry struct {
	PublicKeyDER []byte // RSA: modulus (big-endian unsigned)
	Exponent     []byte // RSA: public exponent (big-endian unsigned)
	ECParams     []byte // EC: DER-encoded curve OID
	ECPoint      []byte // EC: DER-encoded OCTET STRING of uncompressed point
	Algorithm    string // "RSA" or "EC"
}

type certDataCache struct {
	mu      sync.RWMutex
	ttl     time.Duration
	pubKeys map[string]*cacheEntry[pubKeyEntry]
	certs   map[string]*cacheEntry[[]byte]
}

func newCertDataCache(ttlSeconds int) *certDataCache {
	if ttlSeconds == 0 {
		ttlSeconds = 3600
	}
	return &certDataCache{
		ttl:     time.Duration(ttlSeconds) * time.Second,
		pubKeys: make(map[string]*cacheEntry[pubKeyEntry]),
		certs:   make(map[string]*cacheEntry[[]byte]),
	}
}

func (c *certDataCache) getPubKey(signerID string) (*pubKeyEntry, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	entry, ok := c.pubKeys[signerID]
	if !ok || entry.isExpired() {
		return nil, false
	}
	return &entry.value, true
}

func (c *certDataCache) setPubKey(signerID string, pk pubKeyEntry) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.pubKeys[signerID] = &cacheEntry[pubKeyEntry]{
		value:     pk,
		expiresAt: time.Now().Add(c.ttl),
	}
}

func (c *certDataCache) getCert(signerID string) ([]byte, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	entry, ok := c.certs[signerID]
	if !ok || entry.isExpired() {
		return nil, false
	}
	return entry.value, true
}

func (c *certDataCache) setCert(signerID string, cert []byte) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.certs[signerID] = &cacheEntry[[]byte]{
		value:     cert,
		expiresAt: time.Now().Add(c.ttl),
	}
}

