package main

import (
	"os"
	"strings"
)

// os.Args is empty inside a c-shared library, so the command line comes from procfs.
func processCommandLine() []string {
	raw, err := os.ReadFile("/proc/self/cmdline")
	if err != nil {
		return os.Args
	}
	trimmed := strings.TrimRight(string(raw), "\x00")
	if trimmed == "" {
		return os.Args
	}
	return strings.Split(trimmed, "\x00")
}

package main

import (
	"encoding/json"
	"fmt"
	"net"
	"net/url"
	"os"
	"runtime"
	"strconv"
	"strings"
	"time"
)

const (
	envConfigPath = "INFISICAL_CONFIG"
	envClientID   = "INFISICAL_UNIVERSAL_AUTH_CLIENT_ID"
	envSecret     = "[REDACTED]"
	envServerURL  = "INFISICAL_SERVER_URL"
	envToken      = "[REDACTED]"

	unixDefaultConfigPath = "/etc/infisical/pkcs11.conf"

	authMethodUniversalAuth = "universal-auth"
	authMethodToken         = "token"
)

type TLSConfig struct {
	CACertPath string `json:"ca_cert_path"`
	SkipVerify bool   `json:"skip_verify"`
}

type CacheConfig struct {
	TokenTTLSeconds  int `json:"token_ttl_seconds"`
	CertTTLSeconds   int `json:"cert_ttl_seconds"`
	SignerTTLSeconds int `json:"signer_ttl_seconds"`
}

type AuthConfig struct {
	Method       string `json:"method"`
	ClientID     string `json:"client_id"`
	ClientSecret string `json:"client_secret"`
	Token        string `json:"token"`
}

type ApprovalConfig struct {
	SigningCount       int      `json:"signing_count"`
	SigningDuration    string   `json:"signing_duration"`
	ExcludeScopeFields []string `json:"exclude_scope_fields"`
	IPAddress          string   `json:"ip_address"`
}

type Config struct {
	ServerURL string         `json:"server_url"`
	Auth      AuthConfig     `json:"auth"`
	TLS       TLSConfig      `json:"tls"`
	Cache     CacheConfig    `json:"cache"`
	Approval  ApprovalConfig `json:"approval"`
	LogLevel  string         `json:"log_level"`
	LogFile   string         `json:"log_file"`
}

func (c *Config) setDefaults() {
	if c.Cache.TokenTTLSeconds == 0 {
		c.Cache.TokenTTLSeconds = 300
	}
	if c.Cache.CertTTLSeconds == 0 {
		c.Cache.CertTTLSeconds = 3600
	}
	if c.Cache.SignerTTLSeconds == 0 {
		c.Cache.SignerTTLSeconds = 300
	}
	if c.LogLevel == "" {
		c.LogLevel = "info"
	}
}

// applyEnvOverrides applies environment variable overrides.
func (c *Config) applyEnvOverrides() {
	if v := os.Getenv(envServerURL); v != "" {
		c.ServerURL = v
	}
	if v := os.Getenv(envClientID); v != "" {
		c.Auth.ClientID = v
	}
	if v := os.Getenv(envSecret); v != "" {
		c.Auth.ClientSecret = v
	}
	// A token in the environment selects token auth and takes precedence over Universal Auth.
	if v := os.Getenv(envToken); v != "" {
		c.Auth.Token = v
		c.Auth.Method = authMethodToken
	}
}

func parseDuration(s string) (time.Duration, error) {
	if strings.HasSuffix(s, "d") {
		days, err := strconv.Atoi(strings.TrimSuffix(s, "d"))
		if err != nil {
			return 0, fmt.Errorf("invalid duration: %s", s)
		}
		return time.Duration(days) * 24 * time.Hour, nil
	}
	return time.ParseDuration(s)
}

func (c *Config) validate() error {
	if c.ServerURL == "" {
		return fmt.Errorf("server_url is required")
	}
	parsedURL, err := url.Parse(c.ServerURL)
	if err != nil {
		return fmt.Errorf("server_url is not a valid URL: %w", err)
	}
	scheme := strings.ToLower(parsedURL.Scheme)
	if scheme != "http" && scheme != "https" {
		return fmt.Errorf("server_url scheme must be http or https, got %q", parsedURL.Scheme)
	}
	if parsedURL.Host == "" {
		return fmt.Errorf("server_url must include a host")
	}
	if c.Auth.Method == "" {
		if c.Auth.Token != "" {
			c.Auth.Method = authMethodToken
		} else {
			c.Auth.Method = authMethodUniversalAuth
		}
	}
	switch c.Auth.Method {
	case authMethodUniversalAuth, authMethodToken:
	default:
		return fmt.Errorf("unsupported auth method: %s (must be 'universal-auth' or 'token')", c.Auth.Method)
	}
	if c.Approval.SigningDuration != "" {
		d, err := parseDuration(c.Approval.SigningDuration)
		if err != nil {
			return fmt.Errorf("invalid approval.signing_duration: %w", err)
		}
		if d < time.Minute || d > 30*24*time.Hour {
			return fmt.Errorf("approval.signing_duration must be between 1m and 30d")
		}
	}
	if c.Approval.SigningCount < 0 {
		return fmt.Errorf("approval.signing_count must be a positive integer")
	}
	if err := ValidateScopeExclusions(c.Approval.ExcludeScopeFields); err != nil {
		return fmt.Errorf("invalid approval.exclude_scope_fields: %w", err)
	}
	if c.Approval.IPAddress != "" && net.ParseIP(c.Approval.IPAddress) == nil {
		return fmt.Errorf("approval.ip_address must be an IP address, got %q", c.Approval.IPAddress)
	}
	return nil
}

func defaultConfigPath() string {
	return defaultConfigPathFor(runtime.GOOS, os.Getenv("ProgramData"))
}

func defaultConfigPathFor(goos, programData string) string {
	if goos != "windows" {
		return unixDefaultConfigPath
	}
	if programData == "" {
		programData = `C:\ProgramData`
	}
	return programData + `\Infisical\pkcs11.conf`
}

func loadConfig() (*Config, error) {
	path := os.Getenv(envConfigPath)
	if path == "" {
		path = defaultConfigPath()
	}

	// Check file permissions on Unix systems (warn if world-readable)
	if runtime.GOOS != "windows" {
		if info, err := os.Stat(path); err == nil {
			perm := info.Mode().Perm()
			if perm&0o044 != 0 {
				fmt.Fprintf(os.Stderr, "[infisical-pkcs11] WARNING: config file %s has permissions %04o — "+
					"this file may contain credentials, consider: chmod 600 %s\n", path, perm, path)
			}
		}
	}

	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("failed to read config file %s: %w", path, err)
	}

	var cfg Config
	if err := json.Unmarshal(data, &cfg); err != nil {
		return nil, fmt.Errorf("failed to parse config file %s: %w", path, err)
	}

	cfg.setDefaults()
	cfg.applyEnvOverrides()
	if err := cfg.validate(); err != nil {
		return nil, fmt.Errorf("invalid config: %w", err)
	}

	return &cfg, nil
}

//go:build darwin

package main

import (
	"bytes"
	"encoding/binary"
	"os"

	"golang.org/x/sys/unix"
)

func processCommandLine() []string {
	raw, err := unix.SysctlRaw("kern.procargs2", os.Getpid())
	if err != nil || len(raw) < 4 {
		return os.Args
	}

	argc := int(binary.LittleEndian.Uint32(raw[:4]))
	if argc <= 0 {
		return os.Args
	}

	rest := raw[4:]
	// Skip the executable path and the NUL padding that follows it.
	execEnd := bytes.IndexByte(rest, 0)
	if execEnd < 0 {
		return os.Args
	}
	rest = rest[execEnd:]
	for len(rest) > 0 && rest[0] == 0 {
		rest = rest[1:]
	}

	args := make([]string, 0, argc)
	for i := 0; i < argc && len(rest) > 0; i++ {
		end := bytes.IndexByte(rest, 0)
		if end < 0 {
			args = append(args, string(rest))
			break
		}
		args = append(args, string(rest[:end]))
		rest = rest[end+1:]
	}

	if len(args) == 0 {
		return os.Args
	}
	return args
}

