	var result signResponse
	resp, err := c.httpClient.R().
		SetAuthToken(token).
		SetBody(req).
		SetResult(&result).
		Post(fmt.Sprintf("/api/v1/cert-manager/signers/%s/sign", signerID))

	if err != nil {
		return nil, &RequestError{Operation: operation, Err: err}
