	}

	if uint(*pulCount) < uint(len(mechs)) {
		*pulCount = C.CK_ULONG(len(mechs))
		return C.CKR_BUFFER_TOO_SMALL
	}

	mechArray := unsafe.Slice(pMechanismList, len(mechs))
	for i, m := range mechs {
